class QuantumVAE(nn.Module):
    def __init__(self):
        self.encoder = nn.Sequential(nn.Linear(128, 64), nn.ReLU(), nn.Linear(64, 32))
        self.decoder = nn.Sequential(nn.Linear(128, 256), nn.ReLU(), nn.Linear(256, 128))
    def forward(self, x):
        z = self.encoder(x)
        return self.decoder(z)
